mapper.select:
SELECT t.id, t.conversion_no, t.warehouse_id, t.convert_type, t.status, t.reason, t.remark, t.audited_at, t.auditor, t.audit_opinion, t.version, t.created_at, t.updated_at, w.warehouse_code, w.name AS warehouse_name FROM inventory_conversion t LEFT JOIN warehouse w ON w.id = t.warehouse_id WHERE t.deleted = FALSE
AND t.conversion_no ILIKE CONCAT('%', #{query.conversionNo}, '%')
AND t.warehouse_id = #{query.warehouseId}
AND t.convert_type = #{query.convertType}
AND t.status = #{query.status}
ORDER BY t.created_at DESC, t.id DESC
